SELECT 'source.documents' AS tbl, count(*) AS n FROM source.documents UNION ALL SELECT 'source.relationships' AS tbl, count(*) AS n FROM source.relationships UNION ALL SELECT 'source.provisions' AS tbl, count(*) AS n FROM source.provisions UNION ALL SELECT 'compliance.requirements' AS tbl, count(*) AS n FROM compliance.requirements UNION ALL SELECT 'compliance.source_facts' AS tbl, count(*) AS n FROM compliance.source_facts UNION ALL SELECT 'compliance.deadlines' AS tbl, count(*) AS n FROM compliance.deadlines UNION ALL SELECT 'mapping.format_coverage' AS tbl, count(*) AS n FROM mapping.format_coverage UNION ALL SELECT 'mapping.format_equivalences' AS tbl, count(*) AS n FROM mapping.format_equivalences UNION ALL SELECT 'audit.rules' AS tbl, count(*) AS n FROM audit.rules UNION ALL SELECT 'audit.runs' AS tbl, count(*) AS n FROM audit.runs UNION ALL SELECT 'audit.results' AS tbl, count(*) AS n FROM audit.results;